      out.write("<!-- JavaScript điều khiển logic vé KN-120 -->\r\n");
      out.write("<script>\r\n");
      out.write("const ctx = '");
      out.write((java.lang.String) org.apache.jasper.runtime.PageContextImpl.proprietaryEvaluate("${pageContext.request.contextPath}", java.lang.String.class, (javax.servlet.jsp.PageContext)_jspx_page_context, null, false));
      out.write("';\r\n");
      out.write("\r\n");
      out.write("// 1. Xem trước đúng như giao diện khai báo trước khi xuất bản [KN-120]\r\n");
      out.write("function openPreviewModal(id) {\r\n");
      out.write("    const modal = new bootstrap.Modal(document.getElementById('previewModal'));\r\n");
      out.write("    modal.show();\r\n");
      out.write("\r\n");
      out.write("    // Reset giao diện\r\n");
      out.write("    document.getElementById('prevCode').innerText = 'Đang tải...';\r\n");
      out.write("    document.getElementById('prevPosition').innerText = 'Đang tải...';\r\n");
      out.write("    document.getElementById('prevDept').innerText = 'Đang tải...';\r\n");
      out.write("    document.getElementById('prevHeadcount').innerText = '--';\r\n");
      out.write("    document.getElementById('prevReason').innerText = '--';\r\n");
      out.write("    document.getElementById('prevSalary').innerText = '--';\r\n");
      out.write("    document.getElementById('prevDeadline').innerText = '--';\r\n");
      out.write("    document.getElementById('prevJd').innerText = '--';\r\n");
      out.write("    document.getElementById('prevReq').innerText = '--';\r\n");
      out.write("    document.getElementById('prevSalaryExpCard').style.display = 'none';\r\n");
      out.write("    document.getElementById('prevModalActions').innerHTML = '';\r\n");
      out.write("\r\n");
      out.write("    fetch(ctx + '/post-publishing/preview?id=' + encodeURIComponent(id))\r\n");
      out.write("        .then(res => res.json())\r\n");
      out.write("        .then(data => {\r\n");
      out.write("            if (data.error) {\r\n");
      out.write("                alert('Lỗi: ' + data.error);\r\n");
      out.write("                return;\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            // Giao diện khai báo\r\n");
      out.write("            document.getElementById('prevCode').innerText = data.code;\r\n");
      out.write("            document.getElementById('prevPosition').innerText = data.positionTitle;\r\n");
      out.write("            document.getElementById('prevDept').innerText = data.departmentName;\r\n");
      out.write("            document.getElementById('prevHeadcount').innerText = data.headcount + ' nhân sự';\r\n");
      out.write("            document.getElementById('prevReason').innerText = data.recruitmentReasonLabel;\r\n");
      out.write("            document.getElementById('prevSalary').innerText = data.formattedSalaryRange;\r\n");
      out.write("            document.getElementById('prevDeadline').innerText = data.deadlineFormatted;\r\n");
      out.write("            document.getElementById('prevJd').innerText = data.jobDescription || 'Chưa soạn bản mô tả công việc.';\r\n");
      out.write("            document.getElementById('prevReq').innerText = data.jobRequirements || 'Chưa soạn yêu cầu ứng viên.';\r\n");
      out.write("\r\n");
      out.write("            if (data.salaryExplanation && data.salaryExplanation.trim() !== '') {\r\n");
      out.write("                document.getElementById('prevSalaryExpCard').style.display = 'block';\r\n");
      out.write("                document.getElementById('prevSalaryExp').innerText = data.salaryExplanation;\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            // Giao diện bài đăng công khai\r\n");
      out.write("            document.getElementById('pubBadgeCode').innerText = data.code;\r\n");
      out.write("            document.getElementById('pubBadgeDeadline').innerText = data.deadlineFormatted;\r\n");
      out.write("            document.getElementById('pubTitle').innerText = data.title;\r\n");
      out.write("            document.getElementById('pubDept').innerText = data.departmentName;\r\n");
      out.write("            document.getElementById('pubSalary').innerText = data.formattedSalaryRange;\r\n");
      out.write("            document.getElementById('pubJd').innerText = data.jobDescription || 'Chưa cập nhật mô tả.';\r\n");
      out.write("            document.getElementById('pubReq').innerText = data.jobRequirements || 'Chưa cập nhật yêu cầu.';\r\n");
      out.write("            document.getElementById('pubHeadcount').innerText = data.headcount + ' vị trí';\r\n");
      out.write("            document.getElementById('pubRecruiter').innerText = data.recruiterName;\r\n");
      out.write("\r\n");
      out.write("            // Huy hiệu điều kiện xuất bản\r\n");
      out.write("            const badge = document.getElementById('previewApprovalBadge');\r\n");
      out.write("            if (data.isApproved) {\r\n");
      out.write("                badge.className = 'badge bg-success text-white px-2 py-1';\r\n");
      out.write("                badge.innerHTML = '<i class=\"bi bi-check-circle-fill me-1\"></i>Đủ điều kiện xuất bản (Đã duyệt)';\r\n");
      out.write("                document.getElementById('prevModalActions').innerHTML = `\r\n");
      out.write("                    <button type=\"button\" class=\"btn btn-success btn-sm px-3\" onclick=\"openPublishFromPreview('${data.id}', '${data.code}', '${data.positionTitle}', ${data.currentVersion})\">\r\n");
      out.write("                        <i class=\"bi bi-upload me-1\"></i> Tiến hành Xuất bản bài đăng này\r\n");
      out.write("                    </button>\r\n");
      out.write("                `;\r\n");
      out.write("            } else {\r\n");
      out.write("                badge.className = 'badge bg-danger text-white px-2 py-1';\r\n");
      out.write("                badge.innerHTML = '<i class=\"bi bi-lock-fill me-1\"></i>Chưa đủ điều kiện: Tin phải duyệt trước khi show công khai';\r\n");
      out.write("                document.getElementById('prevModalActions').innerHTML = `\r\n");
      out.write("                    <button type=\"button\" class=\"btn btn-outline-warning btn-sm\" onclick=\"quickApprove('${data.id}', '${data.code}', '${data.positionTitle}')\">\r\n");
      out.write("                        <i class=\"bi bi-check2-circle me-1\"></i> Phê duyệt tin ngay\r\n");
      out.write("                    </button>\r\n");
      out.write("                `;\r\n");
      out.write("            }\r\n");
      out.write("        })\r\n");
      out.write("        .catch(err => {\r\n");
      out.write("            alert('Lỗi tải dữ liệu xem trước: ' + err);\r\n");
      out.write("        });\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("function openPublishFromPreview(id, code, pos, ver) {\r\n");
      out.write("    const prevEl = document.getElementById('previewModal');\r\n");
      out.write("    const prevInst = bootstrap.Modal.getInstance(prevEl);\r\n");
      out.write("    if (prevInst) prevInst.hide();\r\n");
      out.write("\r\n");
      out.write("    setTimeout(() => {\r\n");
      out.write("        openPublishModal(id, code, pos, ver);\r\n");
      out.write("    }, 400);\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("// 2. Mở Modal Xuất bản bài đăng\r\n");
      out.write("function openPublishModal(id, code, pos, ver) {\r\n");
      out.write("    document.getElementById('pubFormReqId').value = id;\r\n");
      out.write("    document.getElementById('pubFormInfo').innerText = code + ' - ' + pos;\r\n");
      out.write("    const nextVer = ver + 1;\r\n");
      out.write("    document.getElementById('pubNextVersionLabel').innerText = 'Bản xuất #' + nextVer;\r\n");
      out.write("    new bootstrap.Modal(document.getElementById('publishModal')).show();\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("// 3. Cảnh báo khi tin chưa duyệt\r\n");
      out.write("function alertNotApproved(id, code, statusLabel) {\r\n");
      out.write("    alert('TIÊU CHÍ BẮT BUỘC (KN-120):\\nTin phải duyệt trước khi show công khai!\\n\\nTin ' + code + ' hiện đang ở trạng thái: ' + statusLabel + '.\\nVui lòng gửi phê duyệt hoặc duyệt tin trước khi xuất bản.');\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("// 4. Mở Modal Lịch sử các bản xuất và thời điểm [KN-120]\r\n");
      out.write("function openHistoryModal(reqId, code, pos) {\r\n");
      out.write("    document.getElementById('historySubTitle').innerText = code + ' - ' + pos;\r\n");
      out.write("    const tbody = document.getElementById('historyTableBody');\r\n");
      out.write("    tbody.innerHTML = '<tr><td colspan=\"6\" class=\"text-center py-4\"><div class=\"spinner-border text-primary spinner-border-sm\"></div> Đang tải lịch sử bản xuất...</td></tr>';\r\n");
      out.write("    document.getElementById('snapshotDetailBox').style.display = 'none';\r\n");
      out.write("\r\n");
      out.write("    new bootstrap.Modal(document.getElementById('historyModal')).show();\r\n");
      out.write("\r\n");
      out.write("    fetch(ctx + '/post-publishing/history?requisitionId=' + encodeURIComponent(reqId))\r\n");
      out.write("        .then(res => res.json())\r\n");
      out.write("        .then(list => {\r\n");
      out.write("            if (!list || list.length === 0) {\r\n");
      out.write("                tbody.innerHTML = '<tr><td colspan=\"6\" class=\"text-center py-4 text-muted\">Chưa có lịch sử bản xuất nào cho bài đăng này.</td></tr>';\r\n");
      out.write("                return;\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            let html = '';\r\n");
      out.write("            list.forEach(item => {\r\n");
      out.write("                const badgeClass = item.status === 'PUBLISHED' ? 'bg-success' : (item.status === 'ARCHIVED' ? 'bg-secondary' : 'bg-warning text-dark');\r\n");
      out.write("                const statusName = item.status === 'PUBLISHED' ? 'Đang áp dụng' : (item.status === 'ARCHIVED' ? 'Lưu trữ' : 'Đã gỡ');\r\n");
      out.write("                html += `\r\n");
      out.write("                    <tr>\r\n");
      out.write("                        <td class=\"fw-bold font-monospace text-primary\">\r\n");
      out.write("                            <i class=\"bi bi-tag-fill me-1\"></i>${item.versionLabel}\r\n");
      out.write("                        </td>\r\n");
      out.write("                        <td class=\"font-monospace text-dark\">\r\n");
      out.write("                            <i class=\"bi bi-clock me-1 text-muted\"></i>${item.formattedPublishedAt}\r\n");
      out.write("                        </td>\r\n");
      out.write("                        <td>\r\n");
      out.write("                            <strong>${item.publishedByName || 'Hệ thống'}</strong>\r\n");
      out.write("                        </td>\r\n");
      out.write("                        <td>\r\n");
      out.write("                            <span class=\"badge bg-light text-secondary border\">${item.channel || 'Website công khai'}</span>\r\n");
      out.write("                        </td>\r\n");
      out.write("                        <td class=\"text-center\">\r\n");
      out.write("                            <span class=\"badge ${badgeClass}\">${statusName}</span>\r\n");
      out.write("                        </td>\r\n");
      out.write("                        <td class=\"text-end pe-3\">\r\n");
      out.write("                            <button type=\"button\" class=\"btn btn-sm btn-outline-info p-1 px-2\" onclick=\"inspectSnapshot('${item.id}')\" title=\"Xem lại dữ liệu snapshot bản này\">\r\n");
      out.write("                                <i class=\"bi bi-file-earmark-code\"></i> Snapshot\r\n");
      out.write("                            </button>\r\n");
      out.write("                        </td>\r\n");
      out.write("                    </tr>\r\n");
      out.write("                `;\r\n");
      out.write("            });\r\n");
      out.write("            tbody.innerHTML = html;\r\n");
      out.write("        })\r\n");
      out.write("        .catch(err => {\r\n");
      out.write("            tbody.innerHTML = '<tr><td colspan=\"6\" class=\"text-center py-3 text-danger\">Lỗi tải lịch sử bản xuất: ' + err + '</td></tr>';\r\n");
      out.write("        });\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("function inspectSnapshot(pubId) {\r\n");
      out.write("    fetch(ctx + '/post-publishing/version-detail?id=' + encodeURIComponent(pubId))\r\n");
      out.write("        .then(res => res.json())\r\n");
      out.write("        .then(pub => {\r\n");
      out.write("            if (pub.error) {\r\n");
      out.write("                alert('Lỗi: ' + pub.error);\r\n");
      out.write("                return;\r\n");
      out.write("            }\r\n");
      out.write("            const box = document.getElementById('snapshotDetailBox');\r\n");
      out.write("            box.style.display = 'block';\r\n");
